INSERT INTO `v1_287a34a9d3bfad7a5b8397b5f2d62f6ab8e5d27eb16d29a01b93ad998eb672d4` VALUES (1, "加速", "【加速】", "ＴＰ回復や行動速度アップにより、キャラのスキルやユニオンバーストの発動数が増加する\n");
INSERT INTO `v1_287a34a9d3bfad7a5b8397b5f2d62f6ab8e5d27eb16d29a01b93ad998eb672d4` VALUES (2, "弱体", "【弱体】", "敵に継続ダメージ系状態異常や弱体効果を付与し、敵を弱体化させる\n");
INSERT INTO `v1_287a34a9d3bfad7a5b8397b5f2d62f6ab8e5d27eb16d29a01b93ad998eb672d4` VALUES (3, "会心", "【会心】", "クリティカルや通常攻撃強化により、攻撃性能を強化する\n");
INSERT INTO `v1_287a34a9d3bfad7a5b8397b5f2d62f6ab8e5d27eb16d29a01b93ad998eb672d4` VALUES (4, "強化", "【強化】", "攻撃力や防御力アップのバフ効果を用いて、キャラを強化する\n");
INSERT INTO `v1_287a34a9d3bfad7a5b8397b5f2d62f6ab8e5d27eb16d29a01b93ad998eb672d4` VALUES (5, "守備", "【守備】", "ＨＰアップやバリア展開により、耐久性能を強化する\n");
